import type { EntityInput, IdeaInput } from "@/lib/schema";
import type { EvidenceGrade } from "@/lib/complementary";

/**
 * Protocol upgrades in radiotherapy, surgery and the time around an operation (Precision and protocol-upgrades run,
 * 20 October 2026, facet 6).
 *
 * A protocol upgrade is a change to how care that already exists is delivered, not a new drug or machine: letting a
 * patient watch their own breath-hold on a screen, giving a week of radiotherapy where three weeks used to be given,
 * letting people drink water until two hours before an operation, sending them home with four weeks of blood
 * thinner. The owner's example started this file, and it is the second record in it: a patient holding a deep
 * breath for radiotherapy holds it more steadily when they can see the measurement of their own hold.
 *
 * Every record is an idea with three tags beyond `protocol-upgrade`:
 *
 *  - exactly one adoption tier. `upgrade:proven-unevenly-used` means randomised or guideline-level evidence of
 *    benefit and a source showing it is not routine everywhere; `upgrade:promising` means some clinical evidence
 *    and an open question; `upgrade:untested` means plausible, with the trial that would settle it in `test`.
 *  - an evidence grade `evidence:<grade>` on the model of src/data/complementary.ts. The grade is for the benefit
 *    the record claims, stated in its hypothesis, and not for the procedure in general.
 *  - `precision` where the upgrade makes delivery more exact (smaller set-up error, steadier breath-hold, more
 *    reproducible anatomy), so the precision matrix of this run can find it.
 *
 * An adoption gap is printed only where a survey, audit, registry or claims analysis measured it, and the record
 * names the country and year of that measurement. Where nothing measures adoption the record says so.
 *
 * Every identifier was resolved through Europe PMC and its abstract read before a figure was taken from it, and the
 * two NICE recommendations quoted were read from the live guideline pages. One remembered identifier was wrong when
 * checked (a DOI recalled for an enhanced-recovery compliance study resolved to a paper on laparoscopic colectomy
 * mortality) and is not used.
 *
 * Records that already existed are supplemented in their own files rather than duplicated here:
 * `idea-acc-single-fraction-palliative-radiotherapy-default` (src/data/ideas-waves/wave-access.ts),
 * `idea-prev-omit-radiotherapy-low-risk-breast-default` (wave-prevention.ts) and
 * `idea-bio2-prehabilitation-standard` (wave-biology-2.ts) gain the protocol-upgrade tags, a measured adoption note
 * where one exists, and the sources behind it. The capacity and payment framings of hypofractionation live in
 * `idea-acc-hypofractionation-default-lmic` and `idea-cost-hypofractionation-payment`; the two hypofractionation
 * records below are the clinic-level protocol change and link to both.
 *
 * UK spelling. Facet 7 of this run writes the protocol upgrades outside radiotherapy and surgery.
 */

const asOf = "2026-10-20";
const doi = (label: string, d: string) => ({ label, url: `https://doi.org/${d}` });

const RT = ["radiation"];
const SURG = ["surgery"];

type Tier = "proven-unevenly-used" | "promising" | "untested";
const T = (tier: Tier, grade: EvidenceGrade, extra: string[] = []) => ["protocol-upgrade", `upgrade:${tier}`, `evidence:${grade}`, ...extra];
const idea = (x: Omit<IdeaInput, "kind" | "asOf">): IdeaInput => ({ kind: "idea", asOf, ...x });

